def gear_cards():
    return '<div class="gear-grid">'+''.join(f'''<article class="gear-card"><p class="gear-category">{p['label']}</p><div class="gear-body"><p class="eyebrow">{p['kind']}</p><h3><a href="/tools/{p['id']}.html">{p['name']}</a></h3><p class="gear-model">{p['brand']} / {p['model']}</p><p>{e(p['lead'])}</p><a class="official-photo-link" href="{p['source']}" target="_blank" rel="noopener noreferrer">メーカーの商品写真を見る ↗</a><a class="gear-detail" href="/tools/{p['id']}.html">寸法・選び方を見る ↗</a></div></article>''' for p in GEAR)+'</div>'

def home_gear_section():
    return '<section class="section wrap" id="gear"><div class="section-heading"><div><p class="eyebrow">OSHI-KATSU TOOLS</p><h2>推し活の道具を、具体的に。</h2></div><p>写真の大きさ、持ち歩く量、ライブでの重さ。<br>自分に合う条件から比べる。</p></div>'+gear_cards()+'<p class="section-note">メーカー情報を確認した選択候補です。実使用レビューではありません。Amazonの個別出品・価格・在庫は未確認です。</p><a class="button" href="/tools.html">4つの道具を比較する ↗</a></section>'

def render_gear_pages(out,page,ext,amazon):
    folder=out/'tools';folder.mkdir(exist_ok=True)
    for p in GEAR:
        rows=''.join('<tr><th>'+e(k)+'</th><td>'+e(v)+'</td></tr>' for k,v in p['specs'])
        body=f'''<div class="wrap"><p class="breadcrumb"><a href="/">ホーム</a> / <a href="/tools.html">収納・参戦の道具</a> / {p['kind']}</p><article class="prose tool-page"><p class="eyebrow">{p['brand']} ／ {p['label']}</p><h1>{p['name']}</h1><p class="article-meta">{p['model']} ／ 情報確認日：2026年11月8日 ／ 広告を含みます</p><figure class="tool-main-photo"><img src="/assets/{p['image']}" alt="{e(p['name']+' '+p['model'])}" width="580" height="420"><figcaption>{ext(p['source'],'画像出典・メーカー公式情報')}</figcaption></figure><p class="lead">{p['lead']}</p><h2>メーカーで確認した仕様</h2><div class="table-wrap"><table><tbody>{rows}</tbody></table></div><h2>こんな使い方を考えている人に</h2><p>{p['fit']}</p><h2>買う前の確認ポイント</h2><p>{p['caution']}</p><div class="callout"><strong>購入先を確認する</strong><p>当サイトでは実使用・坂道グッズとの個別適合・Amazonの現在の出品や在庫は確認していません。品番・サイズ・入数・色を購入画面で照合してください。</p>{ext(amazon(p['q']),'Amazonでこの品番を探す',True)}{ext(p['source'],'メーカーの仕様を見る')}</div><p><a href="/notes/{p['pair']}.html">使い方と選び方のノートへ ↗</a></p><p><a href="/tools.html">4つの道具を比較する ↗</a></p></article></div>'''
        (folder/(p['id']+'.html')).write_text(page(p['name']+' '+p['model'],body))
    rows=''.join(f'''<tr><td><a href="/tools/{p['id']}.html">{e(p['name'])}<br>{e(p['model'])}</a></td><td>{p['kind']}</td><td>{e(p['specs'][0][0])}<br>{e(p['specs'][0][1])}</td><td>{e(p['specs'][1][0])}：{e(p['specs'][1][1])}</td></tr>''' for p in GEAR)
    body='<div class="wrap section"><p class="breadcrumb"><a href="/">ホーム</a> / 収納・参戦の道具</p><div class="section-heading"><div><p class="eyebrow">OSHI-KATSU TOOLS</p><h1>収納も、次の現場も。<br>自分に合う道具を選ぶ。</h1></div></div><p class="lead">L判の写真と小さなカードでは、選ぶ収納も違います。具体的な仕様から4つの選択候補を比較できます。</p>'+gear_cards()+'<section class="tool-comparison"><h2>仕様と用途を並べて比較</h2><p>本体の外寸と収納可能な内寸は別の情報です。実際に入れるものは、スリーブや台座も含めて測ってください。</p><div class="table-wrap"><table><thead><tr><th>商品</th><th>考えている用途</th><th>寸法・倍率</th><th>ほかの仕様</th></tr></thead><tbody>'+rows+'</tbody></table></div></section><p class="section-note">メーカー情報をもとにした紹介で、実使用レビューや人気順のランキングではありません。Amazonへのリンクは広告を含む検索リンクです。</p></div>'
    (out/'tools.html').write_text(page('収納・参戦用品を比較',body))
